def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if n == 0:
        return []
    order = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(order)}
    m = len(order)
    bit = [0] * (m + 1)

    def add(i: int, d: int) -> None:
        while i <= m:
            bit[i] += d
            i += i & -i

    def pref(i: int) -> int:
        s = 0
        while i:
            s += bit[i]
            i -= i & -i
        return s

    ans = [0] * n
    for i, x in enumerate(a):
        r = rank[x]
        ans[i] = pref(m) - pref(r)
        add(r, 1)
        if i >= k:
            add(rank[a[i - k]], -1)
    return ans
